section=H.fragment_fromstring('<section id="included-services"><div class="section-title"><h2>الخدمات المشمولة في الخطتين</h2><p>تبدأ كل خطة بتحديد أهداف المحتوى ورسائله، وتمتد إلى إنتاج القطع وتسليمها مع جدول يوضح توزيعها خلال الشهر.</p></div><div class="included-grid"></div></section>');grid=section.xpath('./div[@class="included-grid"]')[0]
items=[('التخطيط الشهري للمحتوى','تحديد الأهداف والرسائل والأفكار وخطة الشهر.','نحدد الجمهور والأهداف والرسائل والأفكار، ونجهّز خطة المحتوى وتوزيع القطع خلال الشهر.'),('الكتابة الإبداعية','نصوص التصميمات والكابشنات والسكريبتات.','نكتب النصوص على التصميمات، والكابشنات بالعربية والإنجليزية، وسكريبتات الريلز وأسئلة المقابلات وفق كل فكرة.'),('إنتاج المحتوى','التصميمات والكاروسيل والموشن والريلز.','نجهّز التصميمات والكاروسيل والموشن جرافيك، ونصور ونمنتج الريلز الجديدة وفق أعداد الخطة المختارة.'),('أغلفة الريلز','صورة غلاف لكل ريل.','نجهّز صورة غلاف لكل ريل ضمن المحتوى المُسلّم.'),('جدول نشر المحتوى','ترتيب القطع وتوزيعها خلال الشهر.','نعدّ جدولًا يوضح ترتيب قطع المحتوى وتوزيعها ومواعيد نشرها المقترحة.'),('المراجعة والتسليم','ملفات نهائية جاهزة للنشر.','نراجع المحتوى ونسلّم الملفات النهائية الجاهزة للنشر، مع الكابشنات وأغلفة الريلز.')]
for title,short,full in items:
 card=H.Element('details',{'class':'included-card'});summary=H.SubElement if False else H.fragment_fromstring('<summary><span class="included-title"></span><span class="included-short"></span><span class="included-action" aria-hidden="true">+</span></summary>');summary.xpath('./span')[0].text=title;summary.xpath('./span')[1].text=short;card.append(summary);para=H.Element('p');para.text=full;card.append(para);grid.append(card)
pricing.addnext(section);p.write_text('<!doctype html>'+H.tostring(d,encoding='unicode',method='html'))
